#!/usr/bin/env bash
# Generates GetawayPlayground.swiftpm (an iOS Swift Playgrounds app) from the app sources.
# Re-run after changing anything in Getaway/ and commit the result.
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
src="$root/Getaway"
out="$root/GetawayPlayground.swiftpm"

rm -rf "$out"
mkdir -p "$out"

cat > "$out/Package.swift" <<'SWIFT'
// swift-tools-version: 5.9

// WARNING:
// This file is generated by scripts/make-playground.sh. Edit that script instead.

import PackageDescription
import AppleProductTypes

let package = Package(
    name: "Getaway",
    platforms: [
        .iOS("17.0")
    ],
    products: [
        .iOSApplication(
            name: "Getaway",
            targets: ["AppModule"],
            bundleIdentifier: "dev.getaway.playground",
            teamIdentifier: "",
            displayVersion: "1.0",
            bundleVersion: "1",
            appIcon: .placeholder(icon: .map),
            accentColor: .presetColor(.cyan),
            supportedDeviceFamilies: [
                .pad,
                .phone
            ],
            supportedInterfaceOrientations: [
                .landscapeRight,
                .landscapeLeft,
                .portrait(.upright)
            ]
        )
    ],
    targets: [
        .executableTarget(
            name: "AppModule",
            path: "."
        )
    ]
)
SWIFT

# Swift sources are copied unchanged, except ShaderLibrary.swift (generated below)
# and the #Preview block, which Swift Playgrounds does not need.
for f in FlyCamera GetawayApp HUDModel InputState MathUtilities MetalTerrainView Renderer TerrainMTKView; do
    cp "$src/$f.swift" "$out/$f.swift"
done
awk '/^#Preview/ { skip = 1 } !skip { print } skip && /^}/ { skip = 0 }' \
    "$src/ContentView.swift" > "$out/ContentView.swift"

# Shaders: inline the shared header and embed everything as one runtime-compiled source string.
{
    cat <<'SWIFT'
import Metal

// WARNING: generated by scripts/make-playground.sh from Getaway/*.metal and ShaderCommon.h.

/// Swift Playgrounds can't be relied on to build .metal files, so the shaders are
/// compiled from source when the app launches.
enum ShaderLibrary {
    static func make(device: MTLDevice) throws -> MTLLibrary {
        do {
            return try device.makeLibrary(source: source, options: nil)
        } catch {
            throw RendererError.shaderCompilation("\(error)")
        }
    }

    private static let source = ##"""
SWIFT
    grep -v '^#pragma once' "$src/ShaderCommon.h"
    for m in Terrain MaterialTextures; do
        echo
        grep -v '^#include "ShaderCommon.h"' "$src/$m.metal"
    done
    echo '"""##'
    echo '}'
} > "$out/ShaderLibrary.swift"

# Playground-only error case for shader compile failures.
cat >> "$out/ShaderLibrary.swift" <<'SWIFT'

extension RendererError {
    static func shaderCompilation(_ log: String) -> RendererError {
        .resourceCreation("shader library (\(log))")
    }
}
SWIFT

echo "Generated $out"
